import{entityInstance as userEntityInstance}from"../entity/user.js";import{getRandomElement}from"../common/other-tools.js";import{createUuid}from"../common/uuid-tools.js";import{hashPassword}from"../common/user-tools.js";export function list(t){const n=t.page||1,e=t.size||15;return userEntityInstance.findAndCountAll({offset:(n-1)*e,limit:e}).then(t=>({list:t.rows.map(t=>t.get({plain:!0})),total:t.count,page:n,size:e}))}export function allList(){return userEntityInstance.findAll().then(t=>t.map(t=>t.get({plain:!0})))}export async function filter(t){return(await allList()).filter(t)}export async function getCurrUserSync(){return(await allList())[0]||null}export async function update(t,n){return t.update(n)}export async function delete_(t){return t?.uId?(await t.destroy(),1):0}export async function findByName(t){const n=await userEntityInstance.findOne({where:{name:t}});return n&&n.get({plain:!0})||void 0}export async function add(t){return(await userEntityInstance.create(t)).get({plain:!0})}export async function find(t){return(await allList()).find(t)}export async function findSync(t){return(await allList()).find(t)}export async function createBaseUserData(){const t=await userEntityInstance.count();if(t>0)throw"已有用户个数: "+t;const n=getRandomElement([6,7,8,9,10,11]),e={uId:createUuid(),initDate:(new Date).getTime(),updateDate:(new Date).getTime(),name:"admin",role:"admin",nickname:"23朵毒蘑菇",synopsis:"欢迎使用 Dumogu Blog",about:"23朵毒蘑菇的 BLOG",password:hashPassword("1234567890",n),avatar:"assets/public/user.jpg"};return await userEntityInstance.create(e),e}